import org.junit.Assert;
import org.junit.Test;

import java.lang.reflect.Type;

public class JsonAdapterNullSafeBehaviorTest {

  // ===== Deserializer tests =====

  @JsonAdapter(value = FooNsfDeserializer.class, nullSafe = false)
  public static class FooNsf {
    final String value;
    FooNsf(String value) { this.value = value; }
  }

  public static class FooNsfDeserializer implements JsonDeserializer<FooNsf> {
    static int calledWithNull = 0;
    static int calledWithNonNull = 0;

    public FooNsfDeserializer() {}

    @Override
    public FooNsf deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) {
      if (json == null || json.isJsonNull()) {
        calledWithNull++;
        return new FooNsf("DEFAULT");
      } else {
        calledWithNonNull++;
        return new FooNsf("NOT_NULL");
      }
    }

    static void reset() {
      calledWithNull = 0;
      calledWithNonNull = 0;
    }
  }

  @JsonAdapter(value = FooSafeDeserializer.class) // default nullSafe = true
  public static class FooSafe {
    final String value;
    FooSafe(String value) { this.value = value; }
  }

  public static class FooSafeDeserializer implements JsonDeserializer<FooSafe> {
    static int calledWithNull = 0;
    static int calledWithNonNull = 0;

    public FooSafeDeserializer() {}

    @Override
    public FooSafe deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) {
      if (json == null || json.isJsonNull()) {
        calledWithNull++;
        // Would normally never be called for JSON null when nullSafe is true
        return new FooSafe("DEFAULT_SHOULD_NOT_HAPPEN");
      } else {
        calledWithNonNull++;
        return new FooSafe("NOT_NULL");
      }
    }

    static void reset() {
      calledWithNull = 0;
      calledWithNonNull = 0;
    }
  }

  @Test
  public void testDeserializer_nullSafeFalse_receivesJsonNullAndReturnsDefault() {
    FooNsfDeserializer.reset();
    Gson gson = new Gson();

    FooNsf result = gson.fromJson("null", FooNsf.class);

    Assert.assertNotNull("With nullSafe=false the deserializer should receive JsonNull and may return a default object", result);
    Assert.assertEquals("DEFAULT", result.value);
    Assert.assertEquals("Deserializer should be invoked once with JsonNull", 1, FooNsfDeserializer.calledWithNull);
    Assert.assertEquals(0, FooNsfDeserializer.calledWithNonNull);
  }

  @Test
  public void testDeserializer_nullSafeTrue_suppressesDeserializerOnJsonNull() {
    FooSafeDeserializer.reset();
    Gson gson = new Gson();

    FooSafe result = gson.fromJson("null", FooSafe.class);

    Assert.assertNull("With nullSafe=true the TreeTypeAdapter should return null (not call deserializer) for JSON null", result);
    Assert.assertEquals("Deserializer should not be invoked for JSON null when nullSafe=true", 0, FooSafeDeserializer.calledWithNull);
    Assert.assertEquals(0, FooSafeDeserializer.calledWithNonNull);
  }

