    static int calledWithNull = 0;
    static int calledWithNonNull = 0;

    public BarNsfSerializer() {}

    @Override
    public JsonElement serialize(BarNsf src, Type typeOfSrc, JsonSerializationContext context) {
      if (src == null) {
        calledWithNull++;
        return new JsonPrimitive("DEFAULT");
      } else {
        calledWithNonNull++;
        return new JsonPrimitive("NOT_NULL");
      }
    }

    static void reset() {
      calledWithNull = 0;
      calledWithNonNull = 0;
    }
  }

