    static int calledWithNull = 0;
    static int calledWithNonNull = 0;

    public BarSafeSerializer() {}

    @Override
    public JsonElement serialize(BarSafe src, Type typeOfSrc, JsonSerializationContext context) {
      if (src == null) {
        calledWithNull++;
        // Would normally never be called for Java null when nullSafe is true
        return new JsonPrimitive("DEFAULT_SHOULD_NOT_HAPPEN");
      } else {
        calledWithNonNull++;
        return new JsonPrimitive("NOT_NULL");
      }
    }

    static void reset() {
      calledWithNull = 0;
      calledWithNonNull = 0;
    }
  }

  @Test
  public void testSerializer_nullSafeFalse_receivesJavaNullAndOutputsCustom() {
    BarNsfSerializer.reset();
    Gson gson = new Gson();

    String json = gson.toJson(null, BarNsf.class);

