import com.google.gson.JsonElement;
import com.google.gson.JsonParseException;
import com.google.gson.JsonSerializationContext;
import com.google.gson.JsonSerializer;
import com.google.gson.annotations.JsonAdapter;
import com.google.gson.JsonPrimitive;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Type;

import static org.junit.Assert.*;

/**
 * Tests for honoring @JsonAdapter(nullSafe=...) when using JsonSerializer/JsonDeserializer,
 * ensuring TreeTypeAdapter respects the nullSafe flag for both read and write paths.
 */
public class JsonAdapterNullSafeForTreeTypeAdapterTest {

  @Before
  public void resetFlags() {
    DeserializerNullSafeFalse.called = false;
    DeserializerNullSafeFalse.lastWasJsonNull = false;

    DeserializerNullSafeTrue.called = false;

    SerializerNullSafeFalse.called = false;
    SerializerNullSafeFalse.lastValueWasNull = false;

    SerializerNullSafeTrue.called = false;
  }

  // ----- Types and Adapters for Deserialization tests -----

  @JsonAdapter(value = DeserializerNullSafeFalse.class, nullSafe = false)
  static class BoxNullSafeFalse {
    final String marker;
    BoxNullSafeFalse(String marker) { this.marker = marker; }
  }

  public static class DeserializerNullSafeFalse implements JsonDeserializer<BoxNullSafeFalse> {
    static volatile boolean called;
    static volatile boolean lastWasJsonNull;

    @Override
    public BoxNullSafeFalse deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context)
        throws JsonParseException {
      called = true;
      lastWasJsonNull = json.isJsonNull();
      // When receiving JSON null we return a default instance to verify that deserializer is invoked
      if (json.isJsonNull()) {
        return new BoxNullSafeFalse("DEFAULT_FROM_NULL");
      }
      // For non-null JSON, not needed for this test, but provide a fallback
      return new BoxNullSafeFalse("NON_NULL_INPUT");
    }
  }

  @JsonAdapter(DeserializerNullSafeTrue.class) // nullSafe defaults to true
  static class BoxNullSafeTrue {
    final String marker;
    BoxNullSafeTrue(String marker) { this.marker = marker; }
  }

  public static class DeserializerNullSafeTrue implements JsonDeserializer<BoxNullSafeTrue> {
    static volatile boolean called;

    @Override
    public BoxNullSafeTrue deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context)
        throws JsonParseException {
      called = true;
      // If called (which should not happen for JSON null when nullSafe=true), return some instance
      return new BoxNullSafeTrue("SHOULD_NOT_BE_USED");
    }
  }

  // ----- Types and Adapters for Serialization tests -----

  @JsonAdapter(value = SerializerNullSafeFalse.class, nullSafe = false)
  static class BoxSerNullSafeFalse {
    final String marker;
    BoxSerNullSafeFalse(String marker) { this.marker = marker; }
  }

  public static class SerializerNullSafeFalse implements JsonSerializer<BoxSerNullSafeFalse> {
    static volatile boolean called;
    static volatile boolean lastValueWasNull;

    @Override
    public JsonElement serialize(BoxSerNullSafeFalse src, Type typeOfSrc, JsonSerializationContext context) {
      called = true;
      lastValueWasNull = (src == null);
      // Produce a custom JSON value to signal invocation on null
      return new JsonPrimitive(src == null ? "SERIALIZED_NULL_MARKER" : "SERIALIZED_NON_NULL");
    }
  }

  @JsonAdapter(SerializerNullSafeTrue.class) // nullSafe defaults to true
  static class BoxSerNullSafeTrue {
    final String marker;
    BoxSerNullSafeTrue(String marker) { this.marker = marker; }
  }

  public static class SerializerNullSafeTrue implements JsonSerializer<BoxSerNullSafeTrue> {
    static volatile boolean called;

    @Override
    public JsonElement serialize(BoxSerNullSafeTrue src, Type typeOfSrc, JsonSerializationContext context) {
      called = true;
      return new JsonPrimitive("SHOULD_NOT_BE_USED");
    }
  }

  // ----- Tests -----

  @Test
  public void deserialization_withNullSafeFalse_invokesDeserializerOnJsonNull() {
    Gson gson = new Gson();

    BoxNullSafeFalse result = gson.fromJson("null", BoxNullSafeFalse.class);

    assertTrue("Deserializer should be called for JSON null when nullSafe=false", DeserializerNullSafeFalse.called);
    assertTrue("Deserializer should receive a JsonNull element", DeserializerNullSafeFalse.lastWasJsonNull);
    assertNotNull("Result should not be null when deserializer handles JSON null", result);
    assertEquals("DEFAULT_FROM_NULL", result.marker);
  }

  @Test
  public void deserialization_withNullSafeTrue_returnsNullAndDoesNotCallDeserializer() {
    Gson gson = new Gson();

    BoxNullSafeTrue result = gson.fromJson("null", BoxNullSafeTrue.class);

    assertNull("Result should be null when nullSafe=true (default)", result);
    assertFalse("Deserializer should not be called for JSON null when nullSafe=true", DeserializerNullSafeTrue.called);
  }

  @Test
  public void serialization_withNullSafeFalse_invokesSerializerOnJavaNull() {
    Gson gson = new Gson();

    String json = gson.toJson(null, BoxSerNullSafeFalse.class);

    assertTrue("Serializer should be called for Java null when nullSafe=false", SerializerNullSafeFalse.called);
    assertTrue("Serializer should receive null value", SerializerNullSafeFalse.lastValueWasNull);
    assertEquals("Expected custom serialization for null", "\"SERIALIZED_NULL_MARKER\"", json);
  }

  @Test
  public void serialization_withNullSafeTrue_writesJsonNullAndDoesNotCallSerializer() {
    Gson gson = new Gson();

    String json = gson.toJson(null, BoxSerNullSafeTrue.class);

    assertEquals("null", json);
    assertFalse("Serializer should not be called for Java null when nullSafe=true", SerializerNullSafeTrue.called);
  }
}

