package com.google.gson.stream;

import org.junit.Test;
import org.junit.Assert;

import java.io.IOException;
import java.io.StringWriter;

public class JsonWriterValueDoubleLeniencyTest {

  @Test
  public void lenientAllowsNaNAndInfinity() throws IOException {
    StringWriter sw = new StringWriter();
    JsonWriter jw = new JsonWriter(sw);
    jw.setLenient(true);

    jw.beginArray();
    jw.value(Double.NaN);
    jw.value(Double.POSITIVE_INFINITY);
    jw.value(Double.NEGATIVE_INFINITY);
    jw.endArray();
    jw.close();

    Assert.assertEquals("[NaN,Infinity,-Infinity]", sw.toString());
  }

  @Test
  public void strictRejectsNaNButWritesDeferredNameFirst() throws IOException {
    StringWriter sw = new StringWriter();
    JsonWriter jw = new JsonWriter(sw);
    // Default is non-lenient
    jw.beginObject();
    jw.name("a");

    try {
      jw.value(Double.NaN);
      Assert.fail("Expected IllegalArgumentException for non-finite double in strict mode");
    } catch (IllegalArgumentException e) {
      Assert.assertEquals("Numeric values must be finite, but was NaN", e.getMessage());
    }

    // Ensure the deferred name was written before the exception was thrown
    // With no indent, beginObject() writes '{' and writeDeferredName() writes the quoted name
    Assert.assertEquals("{\"a\"", sw.toString());
  }
}

