/**
 * Tests for honoring @JsonAdapter(nullSafe) when using JsonSerializer / JsonDeserializer.
 * Ensures that when nullSafe=false, TreeTypeAdapter delegates nulls to the custom adapter,
 * and when nullSafe=true (default), Gson handles nulls without invoking the custom adapter.
 */
public class JsonAdapterNullSafeBehaviorTest {

  // ----- Deserialization tests -----

  @JsonAdapter(value = FooDeserializer.class, nullSafe = false)
  public static class FooNonNullSafe {
    final String label;
    FooNonNullSafe(String label) { this.label = label; }
  }

  @JsonAdapter(value = FooDeserializer.class) // default nullSafe = true
  public static class FooSafe {
    final String label;
    FooSafe(String label) { this.label = label; }
  }

  public static class FooDeserializer implements JsonDeserializer<Object> {
    @Override
    public Object deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context)
        throws JsonParseException {
      // For null JSON values, return a default instance; for other values, use a simple mapping.
      String clsName = typeOfT.toString();
      if (json.isJsonNull()) {
        if (clsName.endsWith("FooNonNullSafe")) {
          return new FooNonNullSafe("fromNull");
        } else if (clsName.endsWith("FooSafe")) {
          // This path should not be reached when nullSafe = true because Gson should return null
          // before calling the deserializer. If it does, fail hard.
          throw new AssertionError("Deserializer should not be called for JSON null when nullSafe=true");
        }
      }
      // For non-null JSON primitives, map the string value
      if (json.isJsonPrimitive()) {
        String v = json.getAsString();
        if (clsName.endsWith("FooNonNullSafe")) {
          return new FooNonNullSafe(v);
        } else if (clsName.endsWith("FooSafe")) {
          return new FooSafe(v);
        }
      }
      throw new JsonParseException("Unexpected JSON for type " + typeOfT + ": " + json);
    }
  }

  @Test
  public void testDeserializerReceivesJsonNullWhenNullSafeFalse() {
    Gson gson = new Gson();

    FooNonNullSafe result = gson.fromJson("null", FooNonNullSafe.class);

    assertNotNull(result);
    assertEquals("fromNull", result.label);
  }

  @Test
  public void testDeserializerReturnsNullWhenNullSafeTrueDefault() {
    Gson gson = new Gson();

    FooSafe result = gson.fromJson("null", FooSafe.class);

    assertNull(result);
  }

  // ----- Serialization tests -----

  @JsonAdapter(value = BarNonNullSafeSerializer.class, nullSafe = false)
  public static class BarNonNullSafe {
    final String value;
    BarNonNullSafe(String value) { this.value = value; }
  }

  @JsonAdapter(value = BarSafeSerializer.class) // default nullSafe = true
  public static class BarSafe {
    final String value;
    BarSafe(String value) { this.value = value; }
  }

  public static class BarNonNullSafeSerializer implements JsonSerializer<BarNonNullSafe> {
    @Override
    public JsonElement serialize(BarNonNullSafe src, Type typeOfSrc, JsonSerializationContext context) {
      // When nullSafe=false, TreeTypeAdapter should call this even if src == null
      if (src == null) {
        return new JsonPrimitive("EMPTY");
      }
      return new JsonPrimitive(src.value);
    }
  }

  public static class BarSafeSerializer implements JsonSerializer<BarSafe> {
    @Override
    public JsonElement serialize(BarSafe src, Type typeOfSrc, JsonSerializationContext context) {
      // With nullSafe=true, this should NOT be called for null src; if it is, fail.
      if (src == null) {
        throw new AssertionError("Serializer should not be called for null when nullSafe=true");
      }
      return new JsonPrimitive(src.value);
    }
  }

  @Test
  public void testSerializerInvokedForNullWhenNullSafeFalse() {
    Gson gson = new Gson();

    String json = gson.toJson(null, BarNonNullSafe.class);

    assertEquals("\"EMPTY\"", json);
  }

  @Test
  public void testSerializerWritesNullWhenNullSafeTrueDefault() {
    Gson gson = new Gson();

    String json = gson.toJson(null, BarSafe.class);

    assertEquals("null", json);
  }
}

